DROP PROCEDURE IF EXISTS spacetime_cleanup_confirmed_test_users;
DELIMITER $$
CREATE PROCEDURE spacetime_cleanup_confirmed_test_users()
main: BEGIN
 DECLARE v_ids JSON;
 DECLARE v_mode VARCHAR(16);
 DECLARE v_count BIGINT DEFAULT 0;
 DECLARE v_now DATETIME;
 DECLARE v_schema VARCHAR(64);
 DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
 SET v_ids=CAST(@cleanup_user_ids AS JSON);
 SET v_mode=UPPER(@cleanup_mode);
 SET v_now=NOW();
 IF DATABASE()<>'shikongxiehou_prod' AND DATABASE() NOT REGEXP '^spacetime_cleanup_rehearsal_[0-9]+$' THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='拒绝在未允许的数据库执行';
 END IF;
 IF JSON_TYPE(v_ids)<>'ARRAY' OR JSON_LENGTH(v_ids)<>@cleanup_expected_users OR @cleanup_expected_users<1 THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='用户清单或预期数量错误';
 END IF;
 SELECT COUNT(DISTINCT id) INTO v_count FROM JSON_TABLE(v_ids,'$[*]' COLUMNS(id BIGINT PATH '$' ERROR ON ERROR)) s WHERE id>0;
 IF v_count<>@cleanup_expected_users THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='用户 ID 重复或无效'; END IF;
 IF EXISTS(SELECT 1 FROM content_operation_log WHERE biz_type='OPS_TEST_CLEANUP' AND action='CLEANUP' AND BINARY remark=BINARY @cleanup_batch AND BINARY JSON_UNQUOTE(JSON_EXTRACT(before_value,'$.scopeHash'))=BINARY SHA2(CAST(v_ids AS CHAR),256)) THEN
  SELECT '已完成，无需重复执行' AS 结果; LEAVE main;
 END IF;
 SELECT COUNT(*) INTO v_count FROM app_user WHERE id IN(SELECT id FROM JSON_TABLE(v_ids,'$[*]' COLUMNS(id BIGINT PATH '$')) scoped) AND deleted=0
  AND (register_source='ADMIN_IMPORT' OR openid REGEXP '^(RICH-QX-USER-|REG-RI-USER-|prd01_edu_scene_)');
 IF v_count<>@cleanup_expected_users THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='用户数量或测试来源已变化，必须重新确认'; END IF;
 SELECT v_count AS 测试账号数, (SELECT COUNT(*) FROM app_user WHERE deleted=0)-v_count AS 保留账号数;
 IF v_mode='PREVIEW' THEN LEAVE main; END IF;
 IF v_mode NOT IN('REHEARSAL','APPLY') OR COALESCE(@cleanup_confirmation,'')<>'清理已确认测试账号，保留共享历史' THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='执行模式或确认文字错误';
 END IF;
 IF DATABASE()='shikongxiehou_prod' THEN
  IF v_mode<>'APPLY' OR COALESCE(@cleanup_writes_paused,0)<>1 OR @@server_uuid<>'16de2a02-d8e0-11f1-b00c-0242ac130006' THEN
   SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='生产执行必须停写并核对实例';
  END IF;
  SET v_schema=@cleanup_archive_schema;
  IF v_schema IS NULL OR v_schema NOT REGEXP '^spacetime_archive_[0-9]{8}_[a-zA-Z0-9_]{1,20}$' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='归档库名错误'; END IF;
  SET @cleanup_archive_ok=0;
  SET @cleanup_sql=CONCAT('SELECT COUNT(*) INTO @cleanup_archive_ok FROM `',v_schema,'`.`_archive_manifest` WHERE table_name=''__run__'' AND state=''COMPLETE'' AND scope_ids=CAST(? AS JSON)');
  PREPARE cleanup_stmt FROM @cleanup_sql; EXECUTE cleanup_stmt USING @cleanup_user_ids; DEALLOCATE PREPARE cleanup_stmt;
  IF @cleanup_archive_ok<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='没有同一名单的完整归档，禁止删除'; END IF;
 END IF;
 START TRANSACTION;
