 SELECT COUNT(*) INTO v_count FROM app_user WHERE id IN(SELECT id FROM JSON_TABLE(v_ids,'$[*]' COLUMNS(id BIGINT PATH '$')) scoped) AND deleted=0;
 IF v_count<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='仍有测试账号未清理，整体回滚'; END IF;
 INSERT INTO content_operation_log(biz_type,biz_id,action,before_value,after_value,remark,create_time,update_time,deleted)
 VALUES('OPS_TEST_CLEANUP',0,'CLEANUP',JSON_OBJECT('scopeHash',SHA2(CAST(v_ids AS CHAR),256),'userCount',JSON_LENGTH(v_ids)),JSON_OBJECT('accounts','logical_deleted','sharedHistory','preserved','archive',@cleanup_archive_schema),@cleanup_batch,v_now,v_now,0);
 IF v_mode='REHEARSAL' THEN ROLLBACK; SELECT '演练全部校验通过，已回滚' AS 结果;
 ELSE COMMIT; SELECT '清理已提交，全部保护校验通过' AS 结果; END IF;
END$$
